import sqlite3

from fastapi import APIRouter, Depends, Header
from fastapi.responses import Response
from pydantic import BaseModel, ConfigDict, StrictInt

from ..deps import Actor, get_actor, get_conn
from ..errors import ApiError, not_found
from ..services import bulk_issue

router = APIRouter(prefix="/api/bulk-issues")


class BulkIssueBody(BaseModel):
    model_config = ConfigDict(extra="forbid")
    course_id: StrictInt


@router.post("")
def create_bulk_issue(
    body: BulkIssueBody,
    idempotency_key: str | None = Header(default=None),
    actor: Actor = Depends(get_actor),
    conn: sqlite3.Connection = Depends(get_conn),
):
    if idempotency_key is None or not 8 <= len(idempotency_key) <= 128:
        raise ApiError(400, "invalid_idempotency_key",
                       "Idempotency-Key header is required (8-128 characters).")
    try:
        # The stored string is returned as-is, so first responses and replays are byte-identical.
        response_json = bulk_issue.run_bulk_issue(
            conn, tenant_id=actor.tenant_id, admin_id=actor.admin_id,
            key=idempotency_key, body=body.model_dump())
    except bulk_issue.KeyReused:
        raise ApiError(409, "idempotency_key_reused",
                       "This Idempotency-Key was already used with a different request.")
    except bulk_issue.CourseNotFound:
        raise not_found()
    return Response(content=response_json, media_type="application/json")
import sqlite3
from typing import Literal

from fastapi import APIRouter, Depends, Query

from .. import queries
from ..deps import Actor, get_actor, get_conn
from ..errors import not_found
from ..services.revoke import revoke_certificate

router = APIRouter(prefix="/api/certificates")

# Unknown values are a 422 here; queries.SORT_COLUMNS / SORT_DIRS map them to SQL.
SortKey = Literal["issued_date", "learner_name", "course_title", "serial", "status"]
SortDir = Literal["asc", "desc"]


@router.get("")
def list_certificates(
    q: str | None = None,
    sort: SortKey = "issued_date",
    dir: SortDir = "desc",
    page: int = Query(1, ge=1),
    page_size: int = Query(20, ge=1, le=100),
    actor: Actor = Depends(get_actor),
    conn: sqlite3.Connection = Depends(get_conn),
):
    return queries.list_certificates(conn, actor.tenant_id, q=q, sort=sort, direction=dir,
                                     page=page, page_size=page_size)


@router.get("/{cert_id}")
def certificate_detail(
    cert_id: int,
    actor: Actor = Depends(get_actor),
    conn: sqlite3.Connection = Depends(get_conn),
):
    cert = queries.get_certificate(conn, actor.tenant_id, cert_id)
    if cert is None:
        raise not_found()
    return cert


@router.post("/{cert_id}/revoke")
def revoke(
    cert_id: int,
    actor: Actor = Depends(get_actor),
    conn: sqlite3.Connection = Depends(get_conn),
):
    cert = revoke_certificate(conn, tenant_id=actor.tenant_id, admin_id=actor.admin_id,
                              cert_id=cert_id)
    if cert is None:
        raise not_found()
    return cert
import csv
import io

from fastapi import APIRouter, Depends
from fastapi.responses import StreamingResponse

from .. import db, queries
from ..deps import Actor, get_actor
from .certificates import SortDir, SortKey

router = APIRouter(prefix="/api/certificates")

CSV_HEADER = ["learner_name", "course_title", "serial", "issued_local_date"]
FORMULA_PREFIXES = ("=", "+", "-", "@", "\t", "\r")


def _safe_cell(value: str) -> str:
    """Stop spreadsheets from running a cell as a formula (CSV injection, per OWASP):
    a leading quote makes Excel/Sheets show it as text. Stored data is unchanged."""
    return "'" + value if value.startswith(FORMULA_PREFIXES) else value


def _csv_chunks(tenant_id: int, q: str | None, sort: str, direction: str):
    """Sync generator: Starlette runs it in the threadpool, so a long export never
    blocks the event loop. It owns its connection, separate from the request's."""
    conn = db.connect()
    try:
        buf = io.StringIO()
        writer = csv.writer(buf, lineterminator="\r\n")
        writer.writerow(CSV_HEADER)
        for rows in queries.iter_export_rows(conn, tenant_id, q=q, sort=sort,
                                             direction=direction):
            writer.writerows([_safe_cell(v) for v in r] for r in rows)
            yield buf.getvalue()
            buf.seek(0)
            buf.truncate()
        if buf.tell():  # header only, when nothing matched
            yield buf.getvalue()
    finally:
        conn.close()


@router.get("/export.csv")
def export_csv(
    q: str | None = None,
    sort: SortKey = "issued_date",
    dir: SortDir = "desc",
    actor: Actor = Depends(get_actor),
):
    return StreamingResponse(
        _csv_chunks(actor.tenant_id, q, sort, dir),
        media_type="text/csv; charset=utf-8",
        headers={"Content-Disposition": 'attachment; filename="certificates.csv"'},
    )
